it.effect("revalidates a native-only fork boundary and reads the new target's completed history", () =>
  Effect.gen(function* () {
    const FORK = "ses_native_only_fork";
    const targetHistory = {
      data: [
        { ...history.data[0], id: "msg_fork_user" },
        { ...history.data[1], id: "msg_fork_answer" },
        { ...history.data[2], id: "msg_fork_idle" },
      ],
      cursor: {},
    };
    const sourceHistory = {
      data: [
        ...history.data,
        { id: "msg_later", type: "user", text: "Continue.", time: { created: 1790656590800 } },
        { ...history.data[1], id: "msg_later_answer", time: { created: 1790656590801, completed: 1790656590802 } },
        { id: "msg_later_idle", type: "idle", outcome: "succeeded", time: { created: 1790656590803 } },
      ],
      cursor: {},
    };
    const { runtime, thread } = yield* resumed([
      out("message.list", { sessionID: SESSION, order: "asc", limit: "100" }),
      reply("message.list", sourceHistory),
      out("message.list", { sessionID: SESSION, order: "asc", limit: "100" }),
      reply("message.list", sourceHistory),
      out("session.fork", { sessionID: SESSION, before: "msg_later" }),
      replyData("session.fork", sessionInfo({ id: FORK })),
      out("message.list", { sessionID: FORK, order: "asc", limit: "100" }),
      reply("message.list", targetHistory),
    ]);
    const source = yield* runtime.readThreadSnapshot({ providerThread: thread });
    const selected = source.nativeHistory?.completedTurnRefs[0];
    if (!selected) throw new Error("The original native transcript did not prove its completed turn.");
    const forked = yield* runtime.forkThread({
      sourceProviderThread: thread,
      nativeCompletedTurnRef: selected,
      targetThreadId: ThreadId.make("thread:opencode2-adapter:native-fork"),
    });
    assert.equal(forked.nativeThreadRef?.nativeId, FORK);
    const target = yield* runtime.readThreadSnapshot({ providerThread: forked });
    assert.deepEqual(target.providerTurns, []);
    assert.deepEqual(target.nativeHistory, {
      nativeSessionId: FORK,
      completedTurnRefs: [{ driver: OPENCODE_PROVIDER, nativeId: "msg_fork_user", strength: "strong" }],
      latestCompletedTurnRef: { driver: OPENCODE_PROVIDER, nativeId: "msg_fork_user", strength: "strong" },
    });
  }).pipe(Effect.scoped),
);

